-- Daily challenges for 2026-11-26: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-11-26. The routine loads the same rows in
-- re-runnable pieces from tools/challenges_sync.py; the GitHub workflow applies this file once
-- the SUPABASE_DB_URL secret is set.
-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('writing-just-for-fun', 'Writing Just for Fun', 'For anyone who used to love writing, or never felt allowed to try. Each day is one small, low pressure way to play with words, from short poems and silly lists to tiny stories and descriptions, written for no one but you.', 'Creativity', 365, array['Self-Care', 'Mindfulness']::text[], 1, '2026-11-26T17:00:00+00:00'::timestamptz),
  ('pacing-your-energy-through-the-day', 'Pacing Your Energy Through the Day', 'For anyone who runs out of steam by midafternoon or crashes after busy days. Each day is one small way to notice where your energy goes, spread out the hard parts, and build in pauses so you have something left in the evening.', 'Burnout', 365, array['Burnout', 'Self-Care', 'Habits']::text[], 1, '2026-11-26T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('writing-just-for-fun', 'pacing-your-energy-through-the-day');

